usage:
```ts
import { dsarInstance } from "@dsar/backend";
import { makeFilesystemStorageAdapter } from "@dsar/storage-filesystem";

const storage = makeFilesystemStorageAdapter({
	baseDir: "./.dsar-artifacts",
	prefix: "artifacts",
});

const runtime = dsarInstance({
	adapters: {
		inbound: "stub",
		notifications: "stub",
		storage,
	},
});
```
